# ============================================================
#  BLASTI Desktop Fix v0.3.2 -- one-click patcher
# ============================================================
#  What this does (everything is automatic):
#    1. Closes any running BLASTI processes (fixes the EBUSY rebuild error)
#    2. Backs up your current apps\desktop\main.js
#    3. Installs the FIXED main.js (startup crash + Prisma paths fixed)
#    4. Installs apps\desktop\scripts\after-pack.js (Prisma packaging hook)
#    5. Adds 'afterPack: scripts/after-pack.js' to electron-builder.yml
#    6. Bumps apps\desktop\package.json to version 0.3.2
#
#  How to run (from your BLASTI-MULTI folder):
#    powershell -ExecutionPolicy Bypass -File .\BLASTI-fix-0.3.2.ps1
# ============================================================
$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "=== BLASTI Desktop Fix v0.3.2 ===" -ForegroundColor Cyan
Write-Host ""

function Find-RepoRoot($start) {
  $p = $start
  while ($p) {
    if (Test-Path (Join-Path $p "apps\desktop\main.js")) { return $p }
    $parent = Split-Path $p -Parent
    if ($parent -eq $p) { return $null }
    $p = $parent
  }
  return $null
}

$root = Find-RepoRoot $PSScriptRoot
if (-not $root) { $root = Find-RepoRoot (Get-Location).Path }
if (-not $root) {
  $root = (Read-Host "Enter the full path to your BLASTI-MULTI folder").Trim('"')
}
if (-not (Test-Path (Join-Path $root "apps\desktop\main.js"))) {
  Write-Host "ERROR: could not find apps\desktop\main.js under '$root'" -ForegroundColor Red
  Write-Host "Put this script inside your BLASTI-MULTI folder and run it again."
  exit 1
}
Write-Host "[1/6] Repo found: $root"

$procs = Get-Process -Name "BLASTI*" -ErrorAction SilentlyContinue
if ($procs) {
  $procs | Stop-Process -Force
  Start-Sleep -Seconds 2
  Write-Host "[2/6] Closed running BLASTI process(es) -- EBUSY unblocked"
} else {
  Write-Host "[2/6] No running BLASTI processes"
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$mainPath = Join-Path $root "apps\desktop\main.js"
Copy-Item $mainPath (Join-Path $root "apps\desktop\main.js.bak-$stamp") -ErrorAction SilentlyContinue
