'@
[IO.File]::WriteAllBytes($hookPath, [Convert]::FromBase64String(($hookB64 -replace '\s','')))
Write-Host "[4/6] scripts\after-pack.js installed (Prisma packaging hook)"

$ymlPath = Join-Path $root "apps\desktop\electron-builder.yml"
$lines = [IO.File]::ReadAllLines($ymlPath)
$hasHook = $false
foreach ($l in $lines) { if ($l -match '^\s*afterPack:') { $hasHook = $true } }
if (-not $hasHook) {
  $out = New-Object System.Collections.Generic.List[string]
  $inserted = $false
  foreach ($l in $lines) {
    $out.Add($l)
    if (-not $inserted -and $l -match '^npmRebuild:') {
      $out.Add("afterPack: scripts/after-pack.js")
      $inserted = $true
    }
  }
  if (-not $inserted) { $out.Add("afterPack: scripts/after-pack.js") }
  [IO.File]::WriteAllLines($ymlPath, $out.ToArray())
  Write-Host "[5/6] electron-builder.yml: afterPack hook registered"
} else {
  Write-Host "[5/6] electron-builder.yml: afterPack already present"
}

$pkgPath = Join-Path $root "apps\desktop\package.json"
$pkgText = [IO.File]::ReadAllText($pkgPath)
if ($pkgText -match '"version"\s*:\s*"0\.3\.2"') {
  Write-Host "[6/6] package.json already at 0.3.2"
} else {
  $pkgText = $pkgText -replace '"version"\s*:\s*"[^"]*"', '"version": "0.3.2"'
  [IO.File]::WriteAllText($pkgPath, $pkgText)
  Write-Host "[6/6] package.json bumped to version 0.3.2"
}

Write-Host ""
Write-Host "ALL DONE -- fixes applied successfully." -ForegroundColor Green
Write-Host ""
Write-Host "Next step: rebuild the app with" -ForegroundColor White
Write-Host "    bun run build:desktop" -ForegroundColor Yellow
Write-Host ""
Write-Host "Then start dist\win-unpacked\BLASTI.exe (or install BLASTI-Setup-0.3.2.exe)."
Write-Host ""
Write-Host "Press Enter to close this window..."
[void](Read-Host)
